// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

/**
 * @title IExecutionModule
 * @notice Interface that all execution modules must implement
 * @dev This allows the protocol to be infinitely extensible
 */
interface IExecutionModule {
    /**
     * @notice Validate a listing before creation
     * @param listingId The listing ID
     * @param seller The seller address
     * @param metadataURI The IPFS metadata URI
     */
    function validate(
        uint256 listingId,
        address seller,
        string calldata metadataURI
    ) external view returns (bool);
    
    /**
     * @notice Called when a purchase is initiated
     * @param listingId The listing being purchased
     * @param buyer The buyer address
     * @param seller The seller address
     * @param amount The purchase amount
     */
    function onPurchase(
        uint256 listingId,
        address buyer,
        address seller,
        uint256 amount
    ) external;
    
    /**
     * @notice Called when delivery is confirmed
     * @param listingId The listing ID
     */
    function onDelivery(uint256 listingId) external;
}

contracts/MarketplaceKernel.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

/**
 * @title MarketplaceKernel
 * @notice The immutable core of the Universal Decentralized Marketplace
 * @dev This contract does NOT know what it's selling - it only manages listings and routes to execution modules
 */
contract MarketplaceKernel {
    // ============ STATE VARIABLES ============
    
    uint256 private _listingIdCounter;
    address public immutable moduleRegistry;
    address public immutable escrowCore;
    address public treasury;
    
    uint256 public protocolFeeBps = 250; // 2.5% default fee
    
    // ============ STRUCTS ============
    
    struct Listing {
        uint256 id;
        address seller;
        uint8 category;              // Dynamic category ID
        address executionModule;     // Which module handles this listing type
        address escrowModule;        // Which escrow variant to use
        address paymentToken;        // ERC20 token or address(0) for native
        uint256 basePrice;
        string metadataURI;          // IPFS schema-driven JSON
        bool active;
        uint256 createdAt;
    }
    
    // ============ MAPPINGS ============
    
    mapping(uint256 => Listing) public listings;
    mapping(address => uint256[]) public sellerListings;
    
    // ============ EVENTS ============
    
    event ListingCreated(
        uint256 indexed listingId,
        address indexed seller,
        uint8 category,
        address executionModule,
        string metadataURI
    );
    
    event ListingUpdated(uint256 indexed listingId, string newMetadataURI);
    event ListingDeactivated(uint256 indexed listingId);
    event PurchaseInitiated(uint256 indexed listingId, address indexed buyer, uint256 amount);
    
    // ============ ERRORS ============
    
    error InvalidModule();
    error ListingNotActive();
    error UnauthorizedSeller();
    error InvalidPrice();
    
    // ============ CONSTRUCTOR ============
    
    constructor(address _moduleRegistry, address _escrowCore, address _treasury) {
        moduleRegistry = _moduleRegistry;
        escrowCore = _escrowCore;
        treasury = _treasury;
    }
    
    // ============ CORE FUNCTIONS ============
    
    /**
     * @notice Create a new listing
     * @param category The marketplace category (0=Product, 1=Service, 2=Asset, etc.)
     * @param executionModule The approved module that will handle this listing's logic
     * @param paymentToken The token for payment (address(0) for native currency)
     * @param basePrice The base price in the smallest unit
     * @param metadataURI IPFS URI containing the schema-driven listing data
     */
    function createListing(
        uint8 category,
        address executionModule,
        address paymentToken,
        uint256 basePrice,
        string calldata metadataURI
    ) external returns (uint256) {
        // Validate module is approved
        if (!IModuleRegistry(moduleRegistry).isApproved(executionModule)) {
            revert InvalidModule();
        }
        
        if (basePrice == 0) revert InvalidPrice();
        
        uint256 listingId = ++_listingIdCounter;
        
        listings[listingId] = Listing({
            id: listingId,
            seller: msg.sender,
            category: category,
            executionModule: executionModule,
            escrowModule: escrowCore, // Default to core escrow
            paymentToken: paymentToken,
            basePrice: basePrice,
            metadataURI: metadataURI,
            active: true,
            createdAt: block.timestamp
        });
        
        sellerListings[msg.sender].push(listingId);
        
        emit ListingCreated(listingId, msg.sender, category, executionModule, metadataURI);
        
        return listingId;
    }
    
    /**
     * @notice Update listing metadata
     * @param listingId The listing to update
     * @param newMetadataURI New IPFS URI
     */
    function updateListing(uint256 listingId, string calldata newMetadataURI) external {
        Listing storage listing = listings[listingId];
        
        if (listing.seller != msg.sender) revert UnauthorizedSeller();
        if (!listing.active) revert ListingNotActive();
        
        listing.metadataURI = newMetadataURI;
        
        emit ListingUpdated(listingId, newMetadataURI);
    }
    
    /**
     * @notice Deactivate a listing
     * @param listingId The listing to deactivate
     */
    function deactivateListing(uint256 listingId) external {
        Listing storage listing = listings[listingId];
        
        if (listing.seller != msg.sender) revert UnauthorizedSeller();
        
        listing.active = false;
        
        emit ListingDeactivated(listingId);
    }
    
    /**
     * @notice Purchase a listing (routes to execution module)
     * @param listingId The listing to purchase
     */
    function purchase(uint256 listingId) external payable {
        Listing memory listing = listings[listingId];
        
        if (!listing.active) revert ListingNotActive();
        
        // Calculate protocol fee
        uint256 fee = (listing.basePrice * protocolFeeBps) / 10000;
        uint256 sellerAmount = listing.basePrice - fee;
        
        // Route to execution module for custom logic
        IExecutionModule(listing.executionModule).onPurchase(
            listingId,
            msg.sender,
            listing.seller,
            sellerAmount
        );
        
        emit PurchaseInitiated(listingId, msg.sender, listing.basePrice);
    }
    
    /**
     * @notice Get all listings by a seller
     * @param seller The seller address
     */
    function getSellerListings(address seller) external view returns (uint256[] memory) {
        return sellerListings[seller];
    }
    
    /**
     * @notice Get listing details
     * @param listingId The listing ID
     */
    function getListing(uint256 listingId) external view returns (Listing memory) {
        return listings[listingId];
    }
}

// ============ INTERFACES ============

interface IModuleRegistry {
    function isApproved(address module) external view returns (bool);
}

interface IExecutionModule {
    function onPurchase(
        uint256 listingId,
        address buyer,
        address seller,
        uint256 amount
    ) external;
}

contracts/ModuleRegistry.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import "@openzeppelin/contracts/access/Ownable.sol";

/**
 * @title ModuleRegistry
 * @notice DAO-controlled registry of approved execution modules
 * @dev Only approved modules can be used to create listings
 */
contract ModuleRegistry is Ownable {
    // ============ STATE VARIABLES ============
    
    mapping(address => bool) public approvedModules;
    mapping(address => string) public moduleMetadata; // IPFS URI describing the module
    
    address[] public allModules;
    
    // ============ EVENTS ============
    
    event ModuleApproved(address indexed module, string metadataURI);
    event ModuleRevoked(address indexed module);
    
    // ============ ERRORS ============
    
    error ModuleAlreadyApproved();
    error ModuleNotApproved();
    
    // ============ CONSTRUCTOR ============
    
    constructor() Ownable(msg.sender) {}
    
    // ============ ADMIN FUNCTIONS ============
    
    /**
     * @notice Approve a new execution module
     * @param module The module contract address
     * @param metadataURI IPFS URI describing the module's purpose and interface
     */
    function approveModule(address module, string calldata metadataURI) external onlyOwner {
        if (approvedModules[module]) revert ModuleAlreadyApproved();
        
        approvedModules[module] = true;
        moduleMetadata[module] = metadataURI;
        allModules.push(module);
        
        emit ModuleApproved(module, metadataURI);
    }
    
    /**
     * @notice Revoke an execution module
     * @param module The module to revoke
     */
    function revokeModule(address module) external onlyOwner {
        if (!approvedModules[module]) revert ModuleNotApproved();
        
        approvedModules[module] = false;
        
        emit ModuleRevoked(module);
    }
    
    // ============ VIEW FUNCTIONS ============
    
    /**
     * @notice Check if a module is approved
     * @param module The module address
     */
    function isApproved(address module) external view returns (bool) {
        return approvedModules[module];
    }
    
    /**
     * @notice Get all approved modules
     */
    function getAllModules() external view returns (address[] memory) {
        return allModules;
    }
    
    /**
     * @notice Get module metadata URI
     * @param module The module address
     */
    function getModuleMetadata(address module) external view returns (string memory) {
        return moduleMetadata[module];
    }
}

contracts/modules/ProductModule.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import "../interfaces/IExecutionModule.sol";

/**
 * @title ProductModule
 * @notice Execution module for physical and digital products
 * @dev Handles one-time payments with delivery confirmation
 */
contract ProductModule is IExecutionModule {
    // ============ STATE VARIABLES ============
    
    address public immutable marketplaceKernel;
    address public immutable escrowCore;
    
    mapping(uint256 => PurchaseData) public purchases;
    
    struct PurchaseData {
        address buyer;
        address seller;
        uint256 amount;
        bool delivered;
        uint256 purchasedAt;
    }
    
    // ============ EVENTS ============
    
    event ProductPurchased(uint256 indexed listingId, address indexed buyer, uint256 amount);
    event ProductDelivered(uint256 indexed listingId);
    
    // ============ ERRORS ============
    
    error Unauthorized();
    error AlreadyDelivered();
    
    // ============ MODIFIERS ============
    
    modifier onlyKernel() {
        if (msg.sender != marketplaceKernel) revert Unauthorized();
        _;
    }
    
    // ============ CONSTRUCTOR ============
    
    constructor(address _marketplaceKernel, address _escrowCore) {
        marketplaceKernel = _marketplaceKernel;
        escrowCore = _escrowCore;
    }
    
    // ============ IMPLEMENTATION ============
    
    function validate(
        uint256,
        address,
        string calldata
    ) external pure override returns (bool) {
        // Products have minimal validation - just need valid metadata
        return true;
    }
    
    function onPurchase(
        uint256 listingId,
        address buyer,
        address seller,
        uint256 amount
    ) external override onlyKernel {
        purchases[listingId] = PurchaseData({
            buyer: buyer,
            seller: seller,
            amount: amount,
            delivered: false,
            purchasedAt: block.timestamp
        });
        
        emit ProductPurchased(listingId, buyer, amount);
    }
    
    function onDelivery(uint256 listingId) external override {
        PurchaseData storage purchase = purchases[listingId];
        
        // Only seller can mark as delivered
        if (msg.sender != purchase.seller) revert Unauthorized();
        if (purchase.delivered) revert AlreadyDelivered();
        
        purchase.delivered = true;
        
        emit ProductDelivered(listingId);
        
        // Buyer has 48 hours to dispute, otherwise auto-release
        // This would trigger escrow release logic
    }
}

contracts/modules/ServiceModule.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import "../interfaces/IExecutionModule.sol";

/**
 * @title ServiceModule
 * @notice Execution module for freelance services and gigs
 * @dev Supports milestone-based payments and partial escrow releases
 */
contract ServiceModule is IExecutionModule {
    // ============ STATE VARIABLES ============
    
    address public immutable marketplaceKernel;
    address public immutable escrowCore;
    
    mapping(uint256 => ServiceData) public services;
    
    struct Milestone {
        string description;
        uint256 amount;
        bool completed;
        bool approved;
    }
    
    struct ServiceData {
        address buyer;
        address seller;
        uint256 totalAmount;
        Milestone[] milestones;
        uint256 completedMilestones;
        uint256 startedAt;
    }
    
    // ============ EVENTS ============
    
    event ServiceStarted(uint256 indexed listingId, address indexed buyer, uint256 totalAmount);
    event MilestoneCompleted(uint256 indexed listingId, uint256 milestoneIndex);
    event MilestoneApproved(uint256 indexed listingId, uint256 milestoneIndex, uint256 amount);
    
    // ============ ERRORS ============
    
    error Unauthorized();
    error InvalidMilestone();
    error MilestoneNotCompleted();
    
    // ============ MODIFIERS ============
    
    modifier onlyKernel() {
        if (msg.sender != marketplaceKernel) revert Unauthorized();
        _;
    }
    
    // ============ CONSTRUCTOR ============
    
    constructor(address _marketplaceKernel, address _escrowCore) {
        marketplaceKernel = _marketplaceKernel;
        escrowCore = _escrowCore;
    }
    
    // ============ IMPLEMENTATION ============
    
    function validate(
        uint256,
        address,
        string calldata
    ) external pure override returns (bool) {
        // Services should have milestone data in metadata
        return true;
    }
    
    function onPurchase(
        uint256 listingId,
        address buyer,
        address seller,
        uint256 amount
    ) external override onlyKernel {
        // Initialize service with empty milestones
        // Milestones would be added separately based on metadata
        ServiceData storage service = services[listingId];
        service.buyer = buyer;
        service.seller = seller;
        service.totalAmount = amount;
        service.startedAt = block.timestamp;
        
        emit ServiceStarted(listingId, buyer, amount);
    }
    
    function onDelivery(uint256 listingId) external override {
        // For services, delivery is handled per milestone
        // This would be called when all milestones are complete
        ServiceData storage service = services[listingId];
        
        if (msg.sender != service.seller) revert Unauthorized();
        
        // Mark final delivery
    }
    
    // ============ SERVICE-SPECIFIC FUNCTIONS ============
    
    /**
     * @notice Mark a milestone as completed (seller)
     * @param listingId The service listing
     * @param milestoneIndex The milestone to mark complete
     */
    function completeMilestone(uint256 listingId, uint256 milestoneIndex) external {
        ServiceData storage service = services[listingId];
        
        if (msg.sender != service.seller) revert Unauthorized();
        if (milestoneIndex >= service.milestones.length) revert InvalidMilestone();
        
        Milestone storage milestone = service.milestones[milestoneIndex];
        milestone.completed = true;
        
        emit MilestoneCompleted(listingId, milestoneIndex);
    }
    
    /**
     * @notice Approve a milestone and release funds (buyer)
     * @param listingId The service listing
     * @param milestoneIndex The milestone to approve
     */
    function approveMilestone(uint256 listingId, uint256 milestoneIndex) external {
        ServiceData storage service = services[listingId];
        
        if (msg.sender != service.buyer) revert Unauthorized();
        if (milestoneIndex >= service.milestones.length) revert InvalidMilestone();
        
        Milestone storage milestone = service.milestones[milestoneIndex];
        if (!milestone.completed) revert MilestoneNotCompleted();
        
        milestone.approved = true;
        service.completedMilestones++;
        
        // Trigger partial escrow release for this milestone amount
        
        emit MilestoneApproved(listingId, milestoneIndex, milestone.amount);
    }
}

